<script setup lang="ts">
import { computed,ref,onMounted,watch,onBeforeUnmount } from 'vue'
import { useApp } from '../stores/app'
import { useSpeech } from '../lib/speech'
import { supabase } from '../lib/supabase'
import Icon from '../components/Icon.vue'
const app=useApp(),speech=useSpeech(),selected=ref(0),error=ref(''),configured=ref(false),audioUrl=ref(''),serverBusy=ref(false),briefs=ref<any[]>([]),audio=ref<HTMLAudioElement>(),activeAudio=ref(''),audioRate=ref(1),resumeAt=ref(0)
const day=(d:string)=>new Intl.DateTimeFormat('en-CA',{timeZone:app.settings.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(d))
const today=day(new Date().toISOString()),posts=computed(()=>app.published.filter(p=>p.published_at&&day(p.published_at)===today)),current=computed(()=>posts.value[selected.value])
function play(i=selected.value){if(!posts.value[i])return;selected.value=i;const p=posts.value[i]!;speech.start(p.title+'。'+p.short_summary,()=>{if(i+1<posts.value.length)play(i+1)})}
async function server(action:string,payload:Record<string,unknown>={}){if(!supabase||app.demo)throw new Error('音频文件服务需要连接私人空间');const r=await supabase.functions.invoke('news-audio',{body:{action,...payload}});if(r.error)throw new Error('音频操作未完成，请查看后台配置或稍后重试');if(r.data?.error)throw new Error(r.data.error);return r.data}
async function load(){if(app.demo)return;try{const r=await server('status');configured.value=r.configured;briefs.value=r.briefs||[]}catch(e){error.value=app.errorMessage(e)}}
let lastSave=0,loadedAudioId=''
async function saveProgress(force=false){if(!app.user||!supabase||!activeAudio.value||loadedAudioId!==activeAudio.value||!audio.value||(!force&&Date.now()-lastSave<10000))return;lastSave=Date.now();const position=Math.max(0,Math.min(7200,audio.value.currentTime||0));await supabase.from('audio_progress').upsert({user_id:app.user.id,audio_id:activeAudio.value,position_seconds:position,playback_rate:audioRate.value,updated_at:new Date().toISOString()},{onConflict:'user_id,audio_id'})}
function changeAudioRate(){if(audio.value)audio.value.playbackRate=audioRate.value;void saveProgress(true)}
async function restore(){if(!audio.value)return;loadedAudioId=activeAudio.value;audio.value.playbackRate=audioRate.value;if(resumeAt.value>0&&resumeAt.value<audio.value.duration-2)audio.value.currentTime=resumeAt.value}
onBeforeUnmount(()=>{void saveProgress(true);audio.value?.pause()})
async function openAudio(id:string){try{await saveProgress(true);loadedAudioId='';audio.value?.pause();speech.stop();activeAudio.value=id;if(supabase&&app.user){const progress=await supabase.from('audio_progress').select('position_seconds,playback_rate').eq('audio_id',id).eq('user_id',app.user.id).maybeSingle();resumeAt.value=progress.data?.position_seconds||0;audioRate.value=progress.data?.playback_rate||1};const r=await server('url',{id});audioUrl.value=r.signedUrl}catch(e){error.value=app.errorMessage(e)}}
async function generate(){serverBusy.value=true;try{const r=await server('generate');if(r.state==='ready')await openAudio(r.id);else app.notify('音频正在生成，请稍后刷新');await load()}catch(e){error.value=app.errorMessage(e)}finally{serverBusy.value=false}}
watch(()=>app.authenticated,v=>{if(!v){speech.stop();audio.value?.pause();audioUrl.value=''}})
onMounted(load)
</script>
<template><div class="page listen-page"><div class="page-heading"><div><div class="eyebrow">LISTEN TO YOUR DAILY EDIT</div><h1>给眼睛放个假<span class="orange">。</span></h1><p>{{today}} · {{app.settings.timezone}} · {{posts.length}} 条已发布内容</p></div><Icon name="Play" :size="34"/></div><section class="form-card"><span class="tiny-orange">今日精选 · 系统朗读</span><h2>{{current?.title||'今天还没有发布内容'}}</h2><p class="listen-summary">{{current?.short_summary||'内容发布后，会自动出现在今天的播放列表。'}}</p><div class="speech-controls"><button class="btn primary" :disabled="!current||!speech.supported" @click="speech.playing.value||speech.paused.value?speech.toggle():play()"><Icon :name="speech.playing.value?'Pause':'Play'" :size="17"/>{{speech.playing.value?'暂停':speech.paused.value?'继续':'开始收听'}}</button><button class="icon-btn" aria-label="停止播报" @click="speech.stop"><Icon name="X"/></button><select :value="speech.rate.value" aria-label="播报速度" @change="speech.changeRate(Number(($event.target as HTMLSelectElement).value))"><option :value="0.8">0.8×</option><option :value="1">1×</option><option :value="1.2">1.2×</option><option :value="1.5">1.5×</option></select></div><p class="form-hint">按顺序朗读文章标题与速读摘要。系统语音不是音频文件；锁屏与后台连续播放取决于设备。</p><p v-if="speech.error.value" class="form-error">{{speech.error.value}}</p></section><section class="form-card listen-list"><h3>今天的播放列表</h3><button v-for="(p,i) in posts" :key="p.id" :class="{active:i===selected}" @click="speech.stop();selected=i;play(i)">{{String(i+1).padStart(2,'0')}} · {{p.title}}</button></section><section class="form-card listen-audio"><h3>每日音频文件</h3><p v-if="!configured">语音合成服务尚未配置。上面的系统朗读可先使用，不会调用付费模型 API。</p><template v-else><p>将今天已核验的 AI 新闻摘要合成为私人 MP3。点击生成才调用服务；每天最多 2 个不同版本，相同内容复用文件。</p><button class="btn outline small" :disabled="serverBusy" @click="generate">{{serverBusy?'正在生成…':'生成今日播报'}}</button></template><div v-for="b in briefs" :key="b.id" class="inbox-actions"><span>{{b.local_date}} · {{b.state==='ready'?'可播放':b.state==='generating'?'生成中':'生成失败'}}</span><button v-if="b.state==='ready'" class="btn outline small" @click="openAudio(b.id)">播放</button></div><audio v-if="audioUrl" ref="audio" :src="audioUrl" controls preload="metadata" @play="speech.stop()" @loadedmetadata="restore" @timeupdate="saveProgress()" @pause="saveProgress(true)" @seeked="saveProgress(true)"/><label v-if="audioUrl">音频速度<select v-model.number="audioRate" aria-label="音频播放速度" @change="changeAudioRate"><option :value="0.8">0.8×</option><option :value="1">1×</option><option :value="1.2">1.2×</option><option :value="1.5">1.5×</option></select></label><button v-if="audioUrl" class="source-link" @click="openAudio(activeAudio)">音频链接过期时，点此重新获取</button><p v-if="error" class="form-error">{{error}}</p></section><RouterLink to="/" class="source-link">回到新闻首页<Icon name="ArrowUpRight" :size="16"/></RouterLink></div></template>
